const HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <meta name=\"description\" content=\"BOG AI is a private AI workspace for coding, study, research, and everyday work.\" />\n  <meta name=\"theme-color\" content=\"#f7f6f2\" />\n  <title>BOG AI</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Mono:wght@300;400;500&family=Manrope:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='14' fill='%23201f1d'/%3E%3Cpath d='M14 17l18 35 18-35-18 9z' fill='%23f7f6f2'/%3E%3Ccircle cx='32' cy='18' r='5' fill='%23cb5b53'/%3E%3C/svg%3E\" />\n  <style>\n    :root{--paper:#f7f6f2;--paper-2:#efede7;--surface:#fff;--ink:#232220;--muted:#77736d;--line:#dedbd4;--line-2:#cbc6bd;--red:#be514b;--red-soft:#f4e7e4;--green:#4d725f;--sidebar:#f1efe9;--code:#201f1d;--code-ink:#f5f2ea;--shadow:0 18px 60px rgba(35,34,32,.08);--radius:16px;color-scheme:light}\n    :root[data-theme=\"dark\"]{--paper:#151515;--paper-2:#242321;--surface:#1d1c1b;--ink:#f3f0e9;--muted:#aaa49b;--line:#363431;--line-2:#4b4843;--red:#e2746c;--red-soft:#3a2423;--green:#88b89e;--sidebar:#1a1918;--code:#0d0d0d;--code-ink:#f5f2ea;--shadow:0 18px 60px rgba(0,0,0,.35);color-scheme:dark}\n    *{box-sizing:border-box}\n    html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--paper);color:var(--ink);font-family:Manrope,system-ui,sans-serif}\n    button,input,textarea{font:inherit}\n    button{color:inherit}\n    .mono{font-family:\"DM Mono\",ui-monospace,monospace}\n    .app{width:100%;height:100vh;height:100dvh;min-height:0;display:grid;grid-template-columns:272px minmax(0,1fr);overflow:hidden}\n    .sidebar{height:100%;min-height:0;overflow:hidden;background:var(--sidebar);border-right:1px solid var(--line);padding:18px 14px 14px;display:flex;flex-direction:column;min-width:0}\n    .brand{height:44px;display:flex;align-items:center;gap:10px;padding:0 10px;margin-bottom:12px}\n    .brand-mark{width:27px;height:27px;background:var(--ink);border-radius:8px;display:grid;place-items:center;position:relative}\n    .brand-mark:before{content:\"\";width:13px;height:15px;background:var(--paper);clip-path:polygon(0 0,50% 100%,100% 0,50% 24%)}\n    .brand-mark:after{content:\"\";position:absolute;width:5px;height:5px;border-radius:50%;background:var(--red);top:5px}\n    .brand strong{font-size:16px;letter-spacing:-.02em}\n    .brand small{font-size:10px;color:var(--red);border:1px solid #dfbbb7;background:#f9eeec;padding:2px 5px;border-radius:999px;margin-left:auto}\n    .new-chat{height:44px;border:1px solid var(--line-2);background:var(--paper);border-radius:12px;display:flex;align-items:center;gap:10px;padding:0 13px;cursor:pointer;box-shadow:0 2px 8px rgba(35,34,32,.03)}\n    .new-chat:hover{border-color:var(--muted);background:var(--surface)}\n    .new-chat span:last-child{margin-left:auto;color:var(--muted);font-size:12px}\n    .nav{display:grid;gap:3px;margin-top:13px}\n    .nav-btn{border:0;background:transparent;border-radius:10px;padding:9px 11px;display:flex;align-items:center;gap:11px;text-align:left;cursor:pointer;font-size:14px}\n    .nav-btn:hover,.nav-btn.active{background:var(--paper-2)}.nav-btn.active{font-weight:600}\n    .nav-icon{width:18px;text-align:center;color:var(--muted)}\n    .section-label{font:500 11px \"DM Mono\",monospace;color:#948f88;letter-spacing:.09em;text-transform:uppercase;padding:20px 11px 8px}\n    .history{overflow:auto;min-height:0}\n    .history button{width:100%;border:0;background:transparent;border-radius:9px;padding:8px 11px;text-align:left;color:#57534e;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer}\n    .history button:hover{background:var(--paper-2);color:var(--ink)}\n    .sidebar-foot{margin-top:auto;border-top:1px solid var(--line);padding-top:11px}\n    .profile{display:flex;align-items:center;gap:10px;padding:9px;border-radius:11px;cursor:pointer}\n    .profile:hover{background:#e7e4dd}\n    .avatar{width:30px;height:30px;border-radius:9px;background:var(--ink);color:white;display:grid;place-items:center;font-size:12px;font-weight:700}\n    .profile-copy{font-size:12px;line-height:1.35}.profile-copy span{display:block;color:var(--muted);font-size:11px}\n    .main{min-width:0;min-height:0;height:100%;max-height:100dvh;display:grid;grid-template-rows:minmax(56px,64px) minmax(0,1fr) auto;overflow:hidden;position:relative;background:var(--paper)}\n    .topbar{height:auto;min-height:56px;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 24px;gap:10px;background:color-mix(in srgb,var(--paper) 90%,transparent);backdrop-filter:blur(12px);z-index:12}\n    .mobile-menu{display:none!important;border:0;background:transparent;font-size:21px}\n    .model-picker{position:relative}\n    .model-btn{border:0;background:transparent;border-radius:10px;padding:8px 10px;display:flex;align-items:center;gap:8px;cursor:pointer;font-weight:650}\n    .model-btn:hover{background:var(--paper-2)}\n    .model-dot{width:7px;height:7px;border-radius:50%;background:var(--red);box-shadow:0 0 0 3px var(--red-soft)}\n    .chev{font-size:11px;color:var(--muted)}\n    .top-actions{margin-left:auto;display:flex;align-items:center;gap:6px}\n    .icon-btn{width:38px;height:38px;border:1px solid transparent;background:transparent;border-radius:10px;display:grid;place-items:center;cursor:pointer;font-size:17px}\n    .icon-btn:hover{background:var(--paper-2);border-color:var(--line)}\n    .connect-btn{height:38px;border:1px solid var(--line-2);background:var(--surface);border-radius:10px;padding:0 13px;cursor:pointer;font:500 12px \"DM Mono\",monospace}\n    .connect-btn:hover{border-color:var(--ink)}\n    .model-menu{display:none;position:absolute;top:45px;left:0;width:330px;background:var(--surface);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);padding:8px;z-index:10}\n    .model-menu.open{display:block}\n    .model-option{width:100%;border:0;background:transparent;border-radius:10px;padding:11px;display:grid;grid-template-columns:1fr auto;gap:3px 12px;text-align:left;cursor:pointer}\n    .model-option:hover,.model-option.selected{background:var(--paper-2)}\n    .model-option strong{font-size:13px}.model-option small{color:var(--muted);font-size:11px;grid-column:1}.tag{font:500 10px \"DM Mono\",monospace;color:var(--red);background:var(--red-soft);padding:3px 6px;border-radius:6px}\n    .workspace{min-width:0;min-height:0;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;scroll-behavior:smooth;display:flex;justify-content:center}\n    .chat{width:min(840px,calc(100% - 40px));padding:clamp(24px,6vh,56px) 0 36px;min-width:0}\n    .welcome{display:block}\n    .eyebrow{font:500 11px \"DM Mono\",monospace;color:var(--red);letter-spacing:.13em;text-transform:uppercase;margin-bottom:15px}\n    h1{font:500 clamp(34px,5vw,54px)/1.02 \"DM Mono\",monospace;letter-spacing:-.05em;margin:0;max-width:700px}\n    .intro{font:400 16px/1.65 \"DM Mono\",monospace;color:#67625c;max-width:680px;margin:20px 0 32px}\n    .modes{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:30px}\n    .mode{min-height:116px;border:1px solid var(--line);background:color-mix(in srgb,var(--surface) 65%,transparent);border-radius:14px;padding:15px;text-align:left;cursor:pointer;transition:.18s ease}\n    .mode:hover{transform:translateY(-2px);border-color:var(--muted);background:var(--surface);box-shadow:0 8px 24px rgba(35,34,32,.05)}\n    .mode-icon{color:var(--red);font-size:18px}.mode strong{display:block;margin:16px 0 5px;font-size:14px}.mode span{display:block;color:var(--muted);font:400 11px/1.45 \"DM Mono\",monospace}\n    .dayline{display:flex;align-items:center;gap:12px;color:#8c867e;font:400 11px \"DM Mono\",monospace;text-transform:uppercase;letter-spacing:.08em}\n    .dayline:before,.dayline:after{content:\"\";height:1px;background:var(--line);flex:1}\n    .thread{display:grid;gap:24px}.message{display:flex;gap:14px;margin:0 auto}.message.pending{opacity:.72}\n    .message.user{justify-content:flex-end}.message.user .bubble{background:var(--paper-2);border:1px solid var(--line);max-width:75%;padding:14px 16px;border-radius:16px 16px 4px 16px}\n    .message.assistant .assistant-mark{width:27px;height:27px;flex:0 0 auto;margin-top:2px;background:var(--ink);color:white;border-radius:8px;display:grid;place-items:center;font:600 11px \"DM Mono\",monospace}\n    .message.assistant .bubble{font-size:15px;line-height:1.7;max-width:720px;min-width:0;overflow-wrap:anywhere}.message.assistant .meta{font:400 11px \"DM Mono\",monospace;color:var(--muted);margin-top:9px}\n    .markdown>:first-child{margin-top:0}.markdown>:last-child{margin-bottom:0}.markdown p{margin:0 0 14px}.markdown h1,.markdown h2,.markdown h3{font-family:\"DM Mono\",monospace;letter-spacing:-.025em;line-height:1.25;margin:24px 0 10px}.markdown h1{font-size:24px}.markdown h2{font-size:20px}.markdown h3{font-size:17px}.markdown ul,.markdown ol{margin:8px 0 16px;padding-left:24px}.markdown li{margin:5px 0}.markdown blockquote{margin:14px 0;padding:2px 0 2px 14px;border-left:3px solid var(--red);color:var(--muted)}.markdown a{color:var(--red)}.markdown code:not(pre code){font:500 .9em \"DM Mono\",monospace;background:var(--paper-2);border:1px solid var(--line);border-radius:5px;padding:2px 5px}.code-block{margin:16px 0;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--code);color:var(--code-ink)}.code-head{height:36px;padding:0 12px;display:flex;align-items:center;border-bottom:1px solid #363432;color:#aaa49b;font:500 11px \"DM Mono\",monospace}.copy-code{margin-left:auto;border:0;background:transparent;color:#ddd7cc;cursor:pointer;font:inherit}.copy-code:hover{color:#fff}.code-block pre{margin:0;padding:16px;overflow:auto;white-space:pre;tab-size:2}.code-block code{font:400 13px/1.65 \"DM Mono\",monospace}.composer-wrap{position:relative;min-width:0;max-height:46dvh;overflow-y:auto;padding:12px 24px 14px;background:var(--paper);border-top:1px solid var(--line);z-index:10}\n    .composer{width:min(840px,100%);margin:auto;background:var(--surface);border:1px solid var(--line-2);border-radius:18px;box-shadow:0 12px 40px rgba(35,34,32,.09);padding:8px}\n    .drop-note{display:none;padding:10px 12px;border:1px dashed var(--red);border-radius:12px;background:var(--red-soft);color:#8b3d38;font:500 12px \"DM Mono\",monospace;margin-bottom:7px}\n    .composer.dragging .drop-note{display:block}\n    .attachments{display:flex;gap:7px;overflow:auto;padding:0 4px}.file-chip{display:flex;align-items:center;gap:7px;border:1px solid var(--line);background:var(--paper);border-radius:10px;padding:7px 9px;font-size:11px;white-space:nowrap}.file-chip button{border:0;background:transparent;color:var(--muted);cursor:pointer;padding:0}.file-status{color:var(--muted);font:500 10px \"DM Mono\",monospace}.file-status.ready{color:var(--green)}.file-status.error{color:var(--red)}\n    textarea{width:100%;min-height:58px;max-height:160px;resize:none;border:0;outline:0;padding:11px 12px 5px;color:var(--ink);background:transparent;font-size:15px;line-height:1.5}\n    textarea::placeholder{color:#9b968e}\n    .composer-foot{display:flex;align-items:center;padding:3px 4px 2px;gap:5px;min-width:0}\n    .tool-btn{height:34px;border:0;background:transparent;border-radius:9px;padding:0 9px;display:flex;align-items:center;gap:7px;color:#6f6a63;font-size:12px;cursor:pointer}\n    .tool-btn:hover{background:var(--paper-2);color:var(--ink)}\n    .send{margin-left:auto;height:40px;min-width:88px;flex:0 0 auto;border:0;border-radius:11px;padding:0 15px;background:var(--ink);color:var(--paper);display:flex;align-items:center;justify-content:center;gap:8px;cursor:pointer;font-weight:700}.send:hover{background:var(--red);color:#fff}.send:disabled{opacity:.55;cursor:wait}\n    .hint{text-align:center;color:#9b968e;font:400 10px \"DM Mono\",monospace;margin-top:9px}\n    .modal-backdrop{position:fixed;inset:0;background:rgba(28,27,25,.3);display:none;place-items:center;padding:20px;z-index:30;backdrop-filter:blur(3px)}\n    .modal-backdrop.open{display:grid}.modal{width:min(560px,100%);background:var(--paper);border:1px solid var(--line-2);border-radius:18px;box-shadow:var(--shadow);padding:22px}.modal-head{display:flex;align-items:flex-start;gap:14px}.modal h2{font:500 24px \"DM Mono\",monospace;margin:0}.modal p{color:var(--muted);font-size:13px;line-height:1.6}.modal-head button{margin-left:auto;border:0;background:transparent;color:var(--ink);font-size:20px;cursor:pointer}.provider{border:1px solid var(--line);background:var(--surface);border-radius:13px;padding:14px;margin-top:12px;display:flex;align-items:center;gap:12px}.provider-logo{width:38px;height:38px;border-radius:10px;background:var(--paper-2);display:grid;place-items:center;font-weight:700}.provider-copy{font-size:13px}.provider-copy span{display:block;color:var(--muted);font-size:11px;margin-top:3px}.provider button{margin-left:auto;border:1px solid var(--line-2);background:var(--paper);color:var(--ink);padding:8px 11px;border-radius:9px;font-size:12px;cursor:pointer}.provider button:hover{border-color:var(--ink)}\n    .search-box{display:flex;gap:8px;margin-top:16px}.search-box input{flex:1;min-width:0;border:1px solid var(--line-2);background:var(--surface);color:var(--ink);border-radius:10px;padding:11px 12px;outline:0}.search-results{display:grid;gap:6px;margin-top:12px;max-height:280px;overflow:auto}.search-result{border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:10px;padding:10px 12px;text-align:left;cursor:pointer}.search-result:hover{border-color:var(--muted)}\n    .toast{position:fixed;right:20px;bottom:20px;background:var(--ink);color:white;border-radius:12px;padding:12px 15px;font-size:12px;box-shadow:var(--shadow);transform:translateY(80px);opacity:0;transition:.25s;z-index:50}.toast.show{transform:translateY(0);opacity:1}\n    .bogling{position:fixed;left:300px;bottom:150px;z-index:9;display:flex;align-items:flex-end;gap:8px;animation:bogRoam 22s ease-in-out infinite;filter:drop-shadow(0 8px 12px rgba(0,0,0,.18));cursor:pointer;user-select:none}.bogling-face{width:48px;height:48px;border:1px solid var(--line-2);border-radius:50% 50% 44% 44%;display:grid;place-items:center;background:var(--surface);font-size:29px;animation:bogBob 2.2s ease-in-out infinite}.bogling-quote{max-width:210px;padding:8px 10px;border:1px solid var(--line);border-radius:12px 12px 12px 3px;background:var(--surface);box-shadow:var(--shadow);font:500 11px/1.4 \"DM Mono\",monospace;opacity:0;transform:translateY(6px);transition:.25s}.bogling.talking .bogling-quote{opacity:1;transform:translateY(0)}\n    @keyframes bogRoam{0%,100%{transform:translateX(0)}45%,55%{transform:translateX(calc(100vw - 650px))}}@keyframes bogBob{0%,100%{transform:translateY(0) rotate(-2deg)}50%{transform:translateY(-8px) rotate(2deg)}}\n    @media(max-width:820px){.app{grid-template-columns:1fr}.sidebar{position:fixed;inset:0 auto 0 0;width:min(280px,86vw);z-index:20;transform:translateX(-100%);transition:.22s;box-shadow:var(--shadow)}.sidebar.open{transform:translateX(0)}.mobile-menu{display:grid!important}.topbar{padding:0 12px}.connect-btn{display:none}.chat{width:min(100% - 24px,720px);padding-top:28px}.modes{grid-template-columns:repeat(2,1fr)}.composer-wrap{padding:10px 12px 12px}.tool-btn span:not(:first-child){display:none}.bogling{left:18px;bottom:135px;animation:bogRoamMobile 18s ease-in-out infinite}@keyframes bogRoamMobile{0%,100%{transform:translateX(0)}45%,55%{transform:translateX(calc(100vw - 90px))}}}\n    @media(max-width:480px){.modes{grid-template-columns:1fr 1fr}.mode{min-height:102px;padding:12px}.connect-btn{display:none}.top-actions{gap:0}.icon-btn{width:34px}.model-btn{padding-left:5px;font-size:12px}.model-dot{display:none}h1{font-size:clamp(30px,11vw,38px)}.intro{font-size:14px;margin:16px 0 22px}.chat{padding-bottom:24px}.model-menu{width:min(330px,calc(100vw - 24px));left:-42px}.composer-wrap{padding:8px}.composer{border-radius:14px}textarea{min-height:46px;padding-top:8px}.send{min-width:72px;padding:0 11px}.markdown h1{font-size:21px}.code-block pre{padding:13px}.bogling-quote{display:none}}\n    @media(max-height:720px){.chat{padding-top:18px;padding-bottom:22px}.composer-wrap{padding-top:7px;padding-bottom:8px}.composer{padding:6px}textarea{min-height:42px;max-height:100px;padding-top:7px}.hint{margin-top:5px}.modes{margin-bottom:18px}.mode{min-height:94px}.mode strong{margin-top:10px}.bogling{bottom:156px}}\n    @media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}.bogling,.bogling-face{animation:none!important}}\n  </style>\n</head>\n<body>\n  <div class=\"app\">\n    <aside class=\"sidebar\" id=\"sidebar\">\n      <div class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\"></span><strong class=\"mono\">BOG AI</strong><small class=\"mono\">private</small></div>\n      <button class=\"new-chat\" id=\"newChat\"><span>＋</span><strong>New conversation</strong><span class=\"mono\">⌘ K</span></button>\n      <nav class=\"nav\" aria-label=\"Main navigation\">\n        <button class=\"nav-btn active\" data-workspace=\"chat\"><span class=\"nav-icon\">◎</span>Chat</button>\n        <button class=\"nav-btn\" data-workspace=\"research\"><span class=\"nav-icon\">⌕</span>Deep research</button>\n        <button class=\"nav-btn\" data-workspace=\"documents\"><span class=\"nav-icon\">▧</span>Documents</button>\n        <button class=\"nav-btn\" data-workspace=\"agents\"><span class=\"nav-icon\">✦</span>Agents</button>\n      </nav>\n      <div class=\"section-label\">Your workspace</div>\n      <nav class=\"nav\">\n        <button class=\"nav-btn\" data-connect=\"Calendar\"><span class=\"nav-icon\">□</span>Calendar</button>\n        <button class=\"nav-btn\" data-connect=\"Mail\"><span class=\"nav-icon\">◇</span>Mail</button>\n        <button class=\"nav-btn\" data-workspace=\"tasks\"><span class=\"nav-icon\">✓</span>Tasks</button>\n      </nav>\n      <div class=\"section-label\">Recent</div>\n      <div class=\"history\" id=\"history\">\n        <button>Build a Python study plan</button><button>Review portfolio component</button><button>Summarize lecture notes</button><button>Plan next week</button>\n      </div>\n      <div class=\"sidebar-foot\"><div class=\"profile\" id=\"settings\"><div class=\"avatar\">Y</div><div class=\"profile-copy\">Your workspace<span>Models & integrations</span></div><span style=\"margin-left:auto;color:var(--muted)\">···</span></div></div>\n    </aside>\n    <main class=\"main\">\n      <header class=\"topbar\">\n        <button class=\"mobile-menu icon-btn\" id=\"mobileMenu\" aria-label=\"Open menu\">☰</button>\n        <div class=\"model-picker\">\n          <button class=\"model-btn\" id=\"modelButton\" aria-haspopup=\"listbox\" aria-expanded=\"false\"><span class=\"model-dot\"></span><span id=\"modelName\">Nemotron 3 Ultra</span><span class=\"chev\">⌄</span></button>\n          <div class=\"model-menu\" id=\"modelMenu\" role=\"listbox\">\n            <button class=\"model-option\" data-model=\"Nemotron 3.5 Lightning\"><strong>Nemotron 3.5 Lightning</strong><span class=\"tag\">fast</span><small>Everyday work · coding · agents</small></button>\n            <button class=\"model-option selected\" data-model=\"Nemotron 3 Ultra\"><strong>Nemotron 3 Ultra</strong><span class=\"tag\">deep</span><small>Complex reasoning · long documents · planning</small></button>\n            <button class=\"model-option\" data-model=\"Nemotron 3 Nano Omni\"><strong>Nemotron 3 Nano Omni</strong><span class=\"tag\">omni</span><small>Images, audio, video, OCR, and transcription</small></button>\n            <button class=\"model-option\" data-model=\"Llama 3.2 Vision\"><strong>Llama 3.2 Vision</strong><span class=\"tag\">vision</span><small>Image reasoning and visual documents</small></button>\n          </div>\n        </div>\n        <div class=\"top-actions\"><button class=\"icon-btn\" id=\"searchButton\" aria-label=\"Search conversations\">⌕</button><button class=\"icon-btn\" id=\"shareButton\" aria-label=\"Copy conversation\">↗</button><button class=\"icon-btn\" id=\"themeToggle\" aria-label=\"Use dark mode\" title=\"Toggle dark mode\">◐</button><button class=\"connect-btn\" id=\"connectTop\">Connect tools</button></div>\n      </header>\n      <div class=\"workspace\" id=\"workspace\">\n        <section class=\"chat\" aria-live=\"polite\">\n          <div class=\"welcome\" id=\"welcome\">\n            <div class=\"eyebrow\">Your private intelligence workspace</div>\n            <h1>What are we working on?</h1>\n            <p class=\"intro\">Code, study, plan, or bring your own files. BOG AI routes each task to the right model while keeping you in control.</p>\n            <div class=\"modes\">\n              <button class=\"mode\" data-prompt=\"Help me build and debug a coding project.\"><span class=\"mode-icon\">&lt;/&gt;</span><strong>Build & code</strong><span>Write, review, debug</span></button>\n              <button class=\"mode\" data-prompt=\"Help me study this topic with a clear lesson and a quiz.\"><span class=\"mode-icon\">◒</span><strong>Study</strong><span>Learn, practice, quiz</span></button>\n              <button class=\"mode\" data-prompt=\"Research this topic deeply and organize the findings.\"><span class=\"mode-icon\">⌕</span><strong>Research</strong><span>Find, compare, synthesize</span></button>\n              <button class=\"mode\" data-prompt=\"Help me plan my day and organize my priorities.\"><span class=\"mode-icon\">✓</span><strong>Plan my day</strong><span>Calendar, mail, tasks</span></button>\n            </div>\n            <div class=\"dayline\">Ready when you are</div>\n          </div>\n          <div class=\"thread\" id=\"thread\"></div>\n        </section>\n      </div>\n      <div class=\"composer-wrap\">\n        <div class=\"composer\" id=\"composer\">\n          <div class=\"drop-note\">Drop files here — documents, code, images, audio, or video</div>\n          <div class=\"attachments\" id=\"attachments\"></div>\n          <textarea id=\"prompt\" rows=\"1\" placeholder=\"Message BOG AI…\" aria-label=\"Message BOG AI\"></textarea>\n          <div class=\"composer-foot\">\n            <button class=\"tool-btn\" id=\"attach\"><span style=\"font-size:19px\">＋</span><span>Add files</span></button>\n            <input id=\"fileInput\" type=\"file\" hidden multiple accept=\".pdf,.doc,.docx,.txt,.md,.csv,.json,.js,.ts,.tsx,.jsx,.py,.java,.c,.cpp,.html,.css,image/*,audio/*,video/*\" />\n            <button class=\"tool-btn\" id=\"voiceButton\"><span style=\"font-size:16px\">◉</span><span>Voice</span></button>\n            <button class=\"tool-btn\" id=\"toolsButton\"><span style=\"font-size:16px\">✦</span><span>Tools</span></button>\n            <button class=\"send\" id=\"send\" aria-label=\"Send message\"><span>Send</span><span aria-hidden=\"true\">↑</span></button>\n          </div>\n        </div>\n        <div class=\"hint\">BOG AI can make mistakes. Review important work.</div>\n      </div>\n      <div class=\"bogling\" id=\"bogling\" role=\"button\" tabindex=\"0\" aria-label=\"Hear a space-sage joke\"><div class=\"bogling-face\" aria-hidden=\"true\">👽</div><div class=\"bogling-quote\" id=\"boglingQuote\"></div></div>\n    </main>\n  </div>\n\n  <div class=\"modal-backdrop\" id=\"modalBackdrop\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modalTitle\">\n    <div class=\"modal\">\n      <div class=\"modal-head\"><div><div class=\"eyebrow\" style=\"margin-bottom:7px\">Workspace setup</div><h2 id=\"modalTitle\">Connect your tools</h2></div><button id=\"closeModal\" aria-label=\"Close\">×</button></div>\n      <p>Calendar and mail require permission from their provider. BOG AI never bypasses that approval.</p>\n      <div class=\"provider\"><div class=\"provider-logo\" style=\"color:#4285f4\">G</div><div class=\"provider-copy\">Google Calendar<span>Authorize the Google Calendar connection offered in ChatGPT</span></div><button data-provider=\"Google Calendar\">How to connect</button></div>\n      <div class=\"provider\"><div class=\"provider-logo\" style=\"color:#1675e0\">M</div><div class=\"provider-copy\">Microsoft 365<span>Outlook, Calendar, OneDrive</span></div><button data-provider=\"Microsoft 365\">Connect</button></div>\n      <div class=\"provider\"><div class=\"provider-logo\" style=\"color:#76b900\">N</div><div class=\"provider-copy\">NVIDIA NIM<span>Nemotron API endpoint</span></div><button data-provider=\"NVIDIA NIM\">Configure</button></div>\n      <p class=\"mono\" style=\"font-size:10px;margin-bottom:0\">Live connections require your account authorization or API credentials.</p>\n    </div>\n  </div>\n  <div class=\"modal-backdrop\" id=\"searchBackdrop\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"searchTitle\">\n    <div class=\"modal\">\n      <div class=\"modal-head\"><div><div class=\"eyebrow\" style=\"margin-bottom:7px\">Find your work</div><h2 id=\"searchTitle\">Search conversations</h2></div><button id=\"closeSearch\" aria-label=\"Close search\">×</button></div>\n      <div class=\"search-box\"><input id=\"searchInput\" type=\"search\" placeholder=\"Search saved conversations…\" aria-label=\"Search saved conversations\" /></div>\n      <div class=\"search-results\" id=\"searchResults\"></div>\n    </div>\n  </div>\n  <div class=\"toast\" id=\"toast\"></div>\n\n  <script>\n    (() => {\n      const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];\n      const prompt=$('#prompt'), composer=$('#composer'), files=[], conversation=[], displayTurns=[], fileStates=new WeakMap();\n      let sending=false,pdfJsPromise,currentConversationId=null;\n      const workspaceModes={\n        chat:{eyebrow:'Your private intelligence workspace',title:'What are we working on?',intro:'Code, study, plan, or bring your own files. BOG AI routes each task to the right model while keeping you in control.',prompt:'',model:'Nemotron 3 Ultra'},\n        research:{eyebrow:'Deep research',title:'Investigate a question',intro:'Define the question, evidence standard, and output you need. BOG AI will structure the investigation and clearly separate evidence from inference.',prompt:'Research this topic deeply. Compare reliable sources, note uncertainty, and organize the findings with citations I can verify: ',model:'Nemotron 3 Ultra'},\n        documents:{eyebrow:'Document workspace',title:'Read, compare, and transform files',intro:'Attach documents or code, then ask for a summary, extraction, comparison, rewrite, or review.',prompt:'Review the attached document and give me a structured summary with key findings and action items.',model:'Nemotron 3 Nano Omni'},\n        agents:{eyebrow:'Agent workspace',title:'Plan a multi-step task',intro:'Describe the outcome and constraints. BOG AI will create a practical plan, work through the steps, and identify where approval is needed.',prompt:'Act as a careful project agent. Break this goal into steps, identify dependencies and risks, then help me execute it: ',model:'Nemotron 3 Ultra'},\n        tasks:{eyebrow:'Task workspace',title:'Turn work into a clear plan',intro:'Capture an objective, deadline, or backlog and turn it into prioritized, concrete next actions.',prompt:'Turn the following into a prioritized task plan with owners, dependencies, and next actions: ',model:'Nemotron 3 Ultra'}\n      };\n\n      function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),2600)}\n      function openModal(title='Connect your tools'){$('#modalTitle').textContent=title;$('#modalBackdrop').classList.add('open')}\n      function closeModal(){$('#modalBackdrop').classList.remove('open')}\n      function scrollChat(){requestAnimationFrame(()=>$('#workspace').scrollTo({top:$('#workspace').scrollHeight,behavior:'smooth'}))}\n      function setModel(name){const option=$$('.model-option').find(o=>o.dataset.model===name);if(option&&!option.classList.contains('selected'))option.click()}\n      function setPrompt(value){prompt.value=value;prompt.dispatchEvent(new Event('input'));prompt.focus()}\n      function activateWorkspace(name){const mode=workspaceModes[name]||workspaceModes.chat;$$('[data-workspace]').forEach(b=>b.classList.toggle('active',b.dataset.workspace===name));if(!displayTurns.length)$('#welcome').style.display='block';$('#welcome .eyebrow').textContent=mode.eyebrow;$('#welcome h1').textContent=mode.title;$('#welcome .intro').textContent=mode.intro;setModel(mode.model);setPrompt(mode.prompt);$('#sidebar').classList.remove('open');if(name==='documents')toast('Attach files below, wait for Ready, then ask what you need')}\n\n      function escapeHtml(value){return String(value).replace(/[&<>\"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[ch]))}\n      function inlineMarkdown(value){let text=escapeHtml(value);text=text.replace(/`([^`]+)`/g,'<code>$1</code>');text=text.replace(/\\*\\*([^*]+)\\*\\*/g,'<strong>$1</strong>');text=text.replace(/__([^_]+)__/g,'<strong>$1</strong>');text=text.replace(/\\*([^*]+)\\*/g,'<em>$1</em>');text=text.replace(/\\[([^\\]]+)\\]\\((https?:\\/\\/[^\\s)]+)\\)/g,'<a href=\"$2\" target=\"_blank\" rel=\"noopener noreferrer\">$1</a>');return text}\n      function renderMarkdown(source){const lines=String(source||'').replace(/\\r\\n?/g,'\\n').split('\\n');let html='',code=[],lang='',list='';const closeList=()=>{if(list){html+=`</${list}>`;list=''}};const closeCode=()=>{const body=escapeHtml(code.join('\\n'));html+=`<div class=\"code-block\"><div class=\"code-head\"><span>${escapeHtml(lang||'code')}</span><button class=\"copy-code\" type=\"button\">Copy</button></div><pre><code>${body}</code></pre></div>`;code=[];lang=''};for(const line of lines){const fence=line.match(/^```\\s*([\\w.+-]*)/);if(fence){if(code.length||lang){closeCode()}else{closeList();lang=fence[1]||'code';code=[]}continue}if(lang){code.push(line);continue}const heading=line.match(/^(#{1,3})\\s+(.+)/);if(heading){closeList();html+=`<h${heading[1].length}>${inlineMarkdown(heading[2])}</h${heading[1].length}>`;continue}const bullet=line.match(/^\\s*[-*]\\s+(.+)/);const ordered=line.match(/^\\s*\\d+[.)]\\s+(.+)/);if(bullet||ordered){const next=ordered?'ol':'ul';if(list!==next){closeList();html+=`<${next}>`;list=next}html+=`<li>${inlineMarkdown((bullet||ordered)[1])}</li>`;continue}closeList();if(/^>\\s?/.test(line)){html+=`<blockquote>${inlineMarkdown(line.replace(/^>\\s?/,''))}</blockquote>`}else if(line.trim()){html+=`<p>${inlineMarkdown(line)}</p>`}}if(lang)closeCode();closeList();return html||'<p></p>'}\n\n      const CONVERSATIONS_KEY='bog-conversations-v1';\n      function getSavedConversations(){try{const value=JSON.parse(localStorage.getItem(CONVERSATIONS_KEY)||'[]');return Array.isArray(value)?value:[]}catch{return[]}}\n      function conversationTitle(){const first=displayTurns.find(turn=>turn.role==='user')?.text||'New conversation';return first.replace(/\\s+/g,' ').trim().slice(0,72)||'New conversation'}\n      function saveConversation(){if(!displayTurns.length)return;if(!currentConversationId)currentConversationId=crypto.randomUUID?.()||`conversation-${Date.now()}`;const record={id:currentConversationId,title:conversationTitle(),updatedAt:Date.now(),model:$('#modelName').textContent,turns:displayTurns.slice(-24)};const items=[record,...getSavedConversations().filter(item=>item.id!==record.id)].slice(0,12);try{localStorage.setItem(CONVERSATIONS_KEY,JSON.stringify(items))}catch{toast('Conversation storage is full. Remove an older browser item and try again.')}renderHistory()}\n      function messageElement(turn,{pending=false}={}){const message=document.createElement('div');message.className=`message ${turn.role}${pending?' pending':''}`;if(turn.role==='assistant'){const mark=document.createElement('div');mark.className='assistant-mark';mark.textContent='B';message.appendChild(mark)}const bubble=document.createElement('div');bubble.className='bubble';const content=document.createElement('div');content.className=turn.role==='assistant'&&!pending?'markdown':'';if(turn.role==='assistant'&&!pending)content.innerHTML=renderMarkdown(turn.text);else content.textContent=turn.text;bubble.appendChild(content);if(turn.role==='assistant'){const meta=document.createElement('div');meta.className='meta';meta.textContent=turn.meta||'';bubble.appendChild(meta)}message.appendChild(bubble);return{message,content}}\n      function renderConversation(){const thread=$('#thread');thread.innerHTML='';displayTurns.forEach(turn=>thread.appendChild(messageElement(turn).message));$('#welcome').style.display=displayTurns.length?'none':'block';scrollChat()}\n      function loadConversation(id){const record=getSavedConversations().find(item=>item.id===id);if(!record)return;currentConversationId=record.id;displayTurns.splice(0,displayTurns.length,...record.turns);conversation.splice(0,conversation.length,...record.turns.map(turn=>({role:turn.role,content:turn.text})));setModel(record.model||'Nemotron 3 Ultra');prompt.value='';renderConversation();$('#sidebar').classList.remove('open');toast('Conversation restored')}\n      function renderHistory(){const saved=getSavedConversations();$('#history').innerHTML='';if(!saved.length){const empty=document.createElement('button');empty.textContent='Your saved conversations will appear here';empty.disabled=true;$('#history').appendChild(empty);return}saved.forEach(item=>{const button=document.createElement('button');button.textContent=item.title;button.title=item.title;button.onclick=()=>loadConversation(item.id);$('#history').appendChild(button)})}\n\n      $('#connectTop').onclick=()=>openModal();$('#settings').onclick=()=>openModal('Models & integrations');$('#closeModal').onclick=closeModal;\n      $('#modalBackdrop').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal()});\n      $$('[data-connect]').forEach(b=>b.onclick=()=>openModal(`Connect ${b.dataset.connect}`));\n      $$('.provider button').forEach(b=>b.onclick=()=>{if(b.dataset.provider==='NVIDIA NIM')toast('NVIDIA NIM is configured securely');else if(b.dataset.provider==='Google Calendar')toast('Authorize the Google Calendar connection offered in this ChatGPT conversation');else toast('Choose and authorize your Microsoft connection in ChatGPT')});\n      $('#modelButton').onclick=()=>{const menu=$('#modelMenu'),open=menu.classList.toggle('open');$('#modelButton').setAttribute('aria-expanded',open)};\n      $$('.model-option').forEach(o=>o.onclick=()=>{$$('.model-option').forEach(x=>x.classList.remove('selected'));o.classList.add('selected');$('#modelName').textContent=o.dataset.model;$('#modelMenu').classList.remove('open');$('#modelButton').setAttribute('aria-expanded','false');toast(`Using ${o.dataset.model}`)});\n      document.addEventListener('click',e=>{if(!e.target.closest('.model-picker'))$('#modelMenu').classList.remove('open')});\n      $('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');\n      $$('[data-workspace]').forEach(b=>b.onclick=()=>activateWorkspace(b.dataset.workspace));\n\n      const savedTheme=localStorage.getItem('voyager-theme');if(savedTheme)document.documentElement.dataset.theme=savedTheme;\n      function updateThemeButton(){const dark=document.documentElement.dataset.theme==='dark';$('#themeToggle').textContent=dark?'☀':'◐';$('#themeToggle').setAttribute('aria-label',dark?'Use light mode':'Use dark mode');document.querySelector('meta[name=\"theme-color\"]').content=dark?'#151515':'#f7f6f2'}\n      $('#themeToggle').onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('voyager-theme',next);updateThemeButton()};updateThemeButton();\n\n      function resetChat(){currentConversationId=null;displayTurns.splice(0);conversation.splice(0);files.splice(0);$('#thread').innerHTML='';$('#welcome').style.display='block';activateWorkspace('chat');prompt.value='';renderFiles();prompt.focus()}\n      $('#newChat').onclick=resetChat;\n      const isPdf=file=>file.type==='application/pdf'||/\\.pdf$/i.test(file.name);\n      function updateSendState(){const reading=files.some(f=>fileStates.get(f)?.status==='reading');$('#send').disabled=sending||reading;$('#send').title=reading?'Please wait while the PDF is read':''}\n      function addFiles(list){const accepted=[...list].filter(f=>{if(f.size>5*1024*1024){toast(`${f.name} is over the 5 MB limit`);return false}return true}),added=[];accepted.forEach(f=>{if(!files.some(x=>x.name===f.name&&x.size===f.size)){files.push(f);added.push(f)}});renderFiles();added.filter(isPdf).forEach(f=>void preparePdf(f).catch(()=>{}));if(accepted.some(f=>/^(image|audio|video)\\//.test(f.type)))setModel('Nemotron 3 Nano Omni');if(added.length)toast(added.some(isPdf)?'Reading the attached PDF…':`${added.length} file${added.length>1?'s':''} attached`)}\n      function renderFiles(){$('#attachments').innerHTML='';files.forEach((f,i)=>{const chip=document.createElement('div');chip.className='file-chip';const type=f.type.startsWith('image/')?'▧':f.type.startsWith('audio/')?'♪':f.type.startsWith('video/')?'▷':'▤',state=fileStates.get(f),status=state?.status==='reading'?'Reading…':state?.status==='ready'?`Ready · ${state.pages} page${state.pages===1?'':'s'}`:state?.status==='error'?'Could not read':'';chip.innerHTML=`<span>${type}</span><span>${escapeHtml(f.name)}</span>${status?`<span class=\"file-status ${state.status}\">${escapeHtml(status)}</span>`:''}<button aria-label=\"Remove ${escapeHtml(f.name)}\">×</button>`;chip.querySelector('button').onclick=()=>{files.splice(i,1);renderFiles()};$('#attachments').appendChild(chip)});updateSendState()}\n      $('#attach').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=e=>addFiles(e.target.files);\n      ['dragenter','dragover'].forEach(evt=>composer.addEventListener(evt,e=>{e.preventDefault();composer.classList.add('dragging')}));\n      ['dragleave','drop'].forEach(evt=>composer.addEventListener(evt,e=>{e.preventDefault();composer.classList.remove('dragging')}));composer.addEventListener('drop',e=>addFiles(e.dataTransfer.files));\n      prompt.addEventListener('input',()=>{prompt.style.height='auto';prompt.style.height=Math.min(prompt.scrollHeight,160)+'px'});\n      prompt.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}});\n      $$('.mode').forEach(m=>m.onclick=()=>setPrompt(m.dataset.prompt));\n\n      const searchBackdrop=$('#searchBackdrop');function searchItems(query=''){const q=query.trim().toLowerCase(),items=getSavedConversations(),matches=items.filter(item=>!q||item.title.toLowerCase().includes(q)||item.turns.some(turn=>turn.text.toLowerCase().includes(q)));$('#searchResults').innerHTML='';if(!matches.length){const empty=document.createElement('div');empty.className='search-result';empty.textContent='No saved conversations found';$('#searchResults').appendChild(empty);return}matches.forEach(item=>{const button=document.createElement('button');button.className='search-result';button.textContent=item.title;button.onclick=()=>{loadConversation(item.id);searchBackdrop.classList.remove('open')};$('#searchResults').appendChild(button)})}\n      $('#searchButton').onclick=()=>{searchBackdrop.classList.add('open');searchItems();setTimeout(()=>$('#searchInput').focus(),0)};$('#closeSearch').onclick=()=>searchBackdrop.classList.remove('open');$('#searchInput').oninput=e=>searchItems(e.target.value);searchBackdrop.addEventListener('click',e=>{if(e.target===e.currentTarget)searchBackdrop.classList.remove('open')});\n      $('#shareButton').onclick=async()=>{if(!displayTurns.length){toast('Start a conversation before sharing');return}const text=displayTurns.map(turn=>`## ${turn.role==='user'?'You':'BOG AI'}\\n\\n${turn.text}`).join('\\n\\n');try{await navigator.clipboard.writeText(text);toast('Entire conversation copied to clipboard')}catch{toast('Clipboard access is unavailable in this browser')}};\n      $('#toolsButton').onclick=()=>openModal('Tools & integrations');\n      let recognition;$('#voiceButton').onclick=()=>{const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){toast('Voice input is not supported in this browser');return}if(recognition){recognition.stop();return}recognition=new SpeechRecognition();recognition.continuous=false;recognition.interimResults=false;recognition.onresult=e=>setPrompt(`${prompt.value}${prompt.value?' ':''}${e.results[0][0].transcript}`);recognition.onerror=()=>toast('Voice input could not start');recognition.onend=()=>{recognition=null;$('#voiceButton').classList.remove('active')};recognition.start();$('#voiceButton').classList.add('active');toast('Listening…')};\n      $('#thread').addEventListener('click',async e=>{const button=e.target.closest('.copy-code');if(!button)return;const code=button.closest('.code-block').querySelector('code').textContent;try{await navigator.clipboard.writeText(code);button.textContent='Copied';setTimeout(()=>button.textContent='Copy',1400)}catch{toast('Clipboard access is unavailable')}});\n\n      function readDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}\n      function readText(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=reject;reader.readAsText(file)})}\n      function getPdfJs(){if(!pdfJsPromise)pdfJsPromise=import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.min.mjs').then(pdfjs=>{pdfjs.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.min.mjs';return pdfjs});return pdfJsPromise}\n      async function preparePdf(file){const existing=fileStates.get(file);if(existing?.promise)return existing.promise;const state={status:'reading',text:'',pages:0,truncated:false,error:'',promise:null};fileStates.set(file,state);renderFiles();state.promise=(async()=>{try{const pdfjs=await getPdfJs(),pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise,chunks=[];let length=0;state.pages=pdf.numPages;for(let pageNumber=1;pageNumber<=pdf.numPages&&length<240000;pageNumber++){const page=await pdf.getPage(pageNumber),content=await page.getTextContent(),text=content.items.map(item=>item.str).join(' ').replace(/\\s+/g,' ').trim();if(text){const block=`[Page ${pageNumber}]\\n${text}`;chunks.push(block);length+=block.length}}state.text=chunks.join('\\n\\n').slice(0,240000);state.truncated=length>240000||chunks.length<pdf.numPages;if(!state.text)throw new Error('This PDF has no extractable text. It may be a scanned document.');state.status='ready';toast(`${file.name} is ready`);return state}catch(error){state.status='error';state.error=error.message||'The PDF could not be read.';toast(`${file.name}: ${state.error}`);throw error}finally{renderFiles()}})();return state.promise}\n      async function filePart(file){if(isPdf(file)){const state=await preparePdf(file);return{type:'text',text:`\\n--- Attached PDF: ${file.name} (${state.pages} pages) ---\\n${state.text}${state.truncated?'\\n\\n[The document was truncated to fit the analysis limit.]':''}\\n--- End PDF ---`}}const kind=file.type.split('/')[0];if(['image','audio','video'].includes(kind)){const url=await readDataUrl(file);return{type:`${kind}_url`,[`${kind}_url`]:{url},name:file.name}}const textTypes=/\\.(txt|md|csv|json|js|jsx|ts|tsx|py|java|c|cpp|h|html|css|xml|yaml|yml|toml|sql|sh|ps1)$/i;if(file.type.startsWith('text/')||textTypes.test(file.name)){const body=(await readText(file)).slice(0,200000);return{type:'text',text:`\\n--- Attached file: ${file.name} ---\\n${body}\\n--- End file ---`}}throw new Error(`${file.name} is attached, but this file type cannot be read yet.`)}\n      async function sendMessage(){const text=prompt.value.trim();if((!text&&!files.length)||sending)return;const pending=[...files],model=$('#modelName').textContent,userText=text||`Please work with ${pending.length} attached file${pending.length>1?'s':''}.`;sending=true;updateSendState();$('#welcome').style.display='none';displayTurns.push({role:'user',text:userText});const userNode=messageElement(displayTurns.at(-1)).message,$thread=$('#thread');$thread.appendChild(userNode);const pendingTurn={role:'assistant',text:pending.some(isPdf)?'Reading your PDF…':'Thinking…',meta:''},pendingNode=messageElement(pendingTurn,{pending:true});$thread.appendChild(pendingNode.message);prompt.value='';prompt.style.height='auto';saveConversation();scrollChat();try{const parts=[{type:'text',text:text||'Please analyze the attached file.'},...(await Promise.all(pending.map(filePart)))];pendingNode.content.textContent='Thinking…';const content=parts.every(part=>part.type==='text')?parts.map(part=>part.text).join('\\n\\n'):parts;conversation.push({role:'user',content});const res=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model,messages:conversation.slice(-12)})});const data=await res.json().catch(()=>({error:'The AI service returned an unreadable response.'}));if(!res.ok)throw new Error(data.error||`AI request failed (${res.status})`);conversation.push({role:'assistant',content:data.content});const answer={role:'assistant',text:data.content,meta:`${data.model||model} · NVIDIA NIM`};displayTurns.push(answer);pendingNode.message.replaceWith(messageElement(answer).message);files.splice(0);renderFiles();saveConversation()}catch(error){const failed={role:'assistant',text:error.message,meta:'Request stopped'};displayTurns.push(failed);pendingNode.message.replaceWith(messageElement(failed).message);saveConversation()}finally{sending=false;updateSendState();scrollChat()}}\n      $('#send').onclick=sendMessage;\n      document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();resetChat()}if(e.key==='Escape'){closeModal();searchBackdrop.classList.remove('open');$('#modelMenu').classList.remove('open');$('#sidebar').classList.remove('open')}});\n      const bogQuotes=['The tabs are many. The focus is one.','A disturbance in the Wi-Fi, I sense.','Your deadline approaches from the dark side.','May your cache be warm and your bugs tiny.','Read the PDF first. Guess later.','Strong coffee, stronger commits.'];let quoteIndex=0,quoteTimer;function showBogQuote(){const bogling=$('#bogling');$('#boglingQuote').textContent=bogQuotes[quoteIndex++%bogQuotes.length];bogling.classList.add('talking');clearTimeout(quoteTimer);quoteTimer=setTimeout(()=>bogling.classList.remove('talking'),4200)}$('#bogling').onclick=showBogQuote;$('#bogling').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showBogQuote()}};setInterval(showBogQuote,18000);setTimeout(showBogQuote,1600);\n      renderHistory();setModel('Nemotron 3 Ultra');\n      if(document.modelContext?.registerTool){const lifecycle=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'start_new_conversation',title:'Start new conversation',description:'Clear the current BOG AI conversation and focus the message composer.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(){resetChat();return{status:'ready'}}},{signal:lifecycle.signal})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'select_ai_model',title:'Select AI model',description:'Select the active AI model in BOG AI.',inputSchema:{type:'object',properties:{model:{type:'string',enum:['Nemotron 3.5 Lightning','Nemotron 3 Ultra','Nemotron 3 Nano Omni','Llama 3.2 Vision']}},required:['model'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute({model}){const option=$$('.model-option').find(o=>o.dataset.model===model);if(!option)throw new Error('Unsupported model');option.click();return{model,status:'selected'}}},{signal:lifecycle.signal})).catch(()=>{})}\n    })();\n  </script>\n</body>\n</html>\n";

const MODELS = {
  "Nemotron 3.5 Lightning": {
    id: "nvidia/nemotron-3.5-lightning-30b-a3b",
    temperature: 1,
    top_p: 0.95,
    max_tokens: 4096,
    chat_template_kwargs: { enable_thinking: false }
  },
  "Nemotron 3 Ultra": {
    id: "nvidia/nemotron-3-ultra-550b-a55b",
    temperature: 0.6,
    top_p: 0.95,
    max_tokens: 16384,
    chat_template_kwargs: { enable_thinking: false }
  },
  "Nemotron 3 Nano Omni": {
    id: "nvidia/nemotron-3-nano-omni-30b-a3b-reasoning",
    temperature: 0.6,
    top_p: 0.95,
    max_tokens: 8192,
    reasoning_budget: 4096
  },
  "Llama 3.2 Vision": {
    id: "meta/llama-3.2-90b-vision-instruct",
    temperature: 0.4,
    top_p: 0.9,
    max_tokens: 4096
  }
};

const SYSTEM = `You are BOG AI, a careful personal AI workspace assistant. Help with coding, study, research, planning, and day-to-day work. Be direct, practical, and honest about uncertainty. Never claim to have sent email, changed a calendar, or modified an external system unless an approved tool confirms it.`;

const securityHeaders = {
  "content-security-policy": "default-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; script-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net; worker-src 'self' blob: https://cdn.jsdelivr.net; img-src 'self' data: https:; media-src 'self' data: blob:; connect-src 'self' https://integrate.api.nvidia.com https://cdn.jsdelivr.net; frame-ancestors 'none'; base-uri 'self'; form-action 'self'",
  "referrer-policy": "strict-origin-when-cross-origin",
  "x-content-type-options": "nosniff",
  "x-frame-options": "DENY",
  "permissions-policy": "camera=(), geolocation=(), payment=()"
};

function json(data, status = 200, headers = {}) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", ...securityHeaders, ...headers }
  });
}

function cleanContent(content) {
  if (typeof content === "string") return content.slice(0, 250000);
  if (!Array.isArray(content)) throw new Error("Message content must be text or a supported attachment list.");
  return content.slice(0, 8).map((part) => {
    if (!part || typeof part !== "object") throw new Error("Invalid attachment part.");
    if (part.type === "text") return { type: "text", text: String(part.text || "").slice(0, 200000) };
    if (["image_url", "audio_url", "video_url"].includes(part.type)) {
      const key = part.type;
      const url = part[key]?.url;
      if (typeof url !== "string" || (!url.startsWith("data:") && !url.startsWith("https://"))) throw new Error("Attachment URL must be a data URL or HTTPS URL.");
      if (url.length > 7_500_000) throw new Error("An attachment is too large. Use files under 5 MB.");
      return { type: part.type, [key]: { url } };
    }
    throw new Error(`Unsupported attachment type: ${part.type || "unknown"}`);
  });
}

function cleanMessages(messages) {
  if (!Array.isArray(messages) || messages.length === 0 || messages.length > 12) throw new Error("Provide between 1 and 12 messages.");
  return messages.map((message) => {
    if (!message || !["user", "assistant"].includes(message.role)) throw new Error("Invalid message role.");
    return { role: message.role, content: cleanContent(message.content) };
  });
}

async function chat(request, env) {
  if (!env.NVIDIA_API_KEY) return json({ error: "NVIDIA_API_KEY is not configured yet. Add it as a deployment secret, then try again." }, 503);
  let body;
  try { body = await request.json(); } catch { return json({ error: "Request body must be valid JSON." }, 400); }
  const config = MODELS[body.model];
  if (!config) return json({ error: "Choose one of the supported NVIDIA models." }, 400);
  let messages;
  try { messages = [{ role: "system", content: SYSTEM }, ...cleanMessages(body.messages)]; }
  catch (error) { return json({ error: error.message }, 400); }

  const payload = { model: config.id, messages, stream: true, ...config };
  delete payload.id;
  let upstream;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 60_000);
  try {
    upstream = await fetch("https://integrate.api.nvidia.com/v1/chat/completions", {
      method: "POST",
      headers: { "authorization": `Bearer ${env.NVIDIA_API_KEY}`, "content-type": "application/json", "accept": "text/event-stream" },
      body: JSON.stringify(payload),
      signal: controller.signal
    });
  } catch (error) {
    if (error?.name === "AbortError") return json({ error: "NVIDIA NIM took too long to respond. Try again or choose another model." }, 504);
    return json({ error: "BOG AI could not reach NVIDIA NIM. Try again shortly." }, 502);
  } finally {
    clearTimeout(timeout);
  }

  const raw = await upstream.text();
  if (!upstream.ok) {
    let data;
    try { data = JSON.parse(raw); } catch { data = null; }
    const message = data?.error?.message || data?.detail || `NVIDIA NIM returned ${upstream.status}.`;
    return json({ error: String(message).slice(0, 800) }, upstream.status >= 400 && upstream.status < 600 ? upstream.status : 502);
  }
  let content = "";
  let usage = null;
  for (const line of raw.split(/\r?\n/)) {
    if (!line.startsWith("data:")) continue;
    const value = line.slice(5).trim();
    if (!value || value === "[DONE]") continue;
    try {
      const chunk = JSON.parse(value);
      content += chunk?.choices?.[0]?.delta?.content || "";
      usage = chunk?.usage || usage;
    } catch {}
  }
  if (!content) {
    try {
      const data = JSON.parse(raw);
      content = data?.choices?.[0]?.message?.content || "";
      usage = data?.usage || null;
    } catch {}
  }
  if (!content) {
    const retryController = new AbortController();
    const retryTimeout = setTimeout(() => retryController.abort(), 60_000);
    try {
      const retryResponse = await fetch("https://integrate.api.nvidia.com/v1/chat/completions", {
        method: "POST",
        headers: { "authorization": `Bearer ${env.NVIDIA_API_KEY}`, "content-type": "application/json", "accept": "application/json" },
        body: JSON.stringify({ ...payload, stream: false }),
        signal: retryController.signal
      });
      const retryData = await retryResponse.json().catch(() => null);
      if (retryResponse.ok) {
        content = retryData?.choices?.[0]?.message?.content || "";
        usage = retryData?.usage || usage;
      }
    } catch {} finally {
      clearTimeout(retryTimeout);
    }
  }
  if (!content) return json({ error: "NVIDIA NIM returned an empty response." }, 502);
  return json({ content, model: config.id, usage });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (request.method === "GET" && url.pathname === "/") {
      return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8", ...securityHeaders } });
    }
    if (request.method === "GET" && url.pathname === "/api/health") {
      return json({ ok: true, configured: Boolean(env.NVIDIA_API_KEY), models: Object.keys(MODELS) });
    }
    if (request.method === "POST" && url.pathname === "/api/chat") return chat(request, env);
    return json({ error: "Not found" }, 404);
  }
};
